draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H / 2 + Math.sin(t) * 50);
  for (let i = 0; i < W; i++) {
    ctx.lineTo(i, H / 2 + Math.sin(t + i * 0.01) * 50);
  }
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t * 2) * 20, H / 2 + Math.cos(t) * 20, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t * 2) * 20, H / 2 + Math.cos(t) * 20, 5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.restore();
}
